"""Generated byte structures and explicit CMS mocks; no signing tools or SDKs."""

from __future__ import annotations

import plistlib
import struct
import zipfile

import pytest

from mobile_audit.binary_analysis import analyze_binary, inspect_macho
from mobile_audit.inputs import inspect_target
from tests.test_ipa_trust import directory_fixture

INFO = plistlib.dumps({"CFBundleIdentifier": "synthetic.signature.scope", "CFBundleExecutable": "App"})
XML = plistlib.dumps({"get-task-allow": True})
XML_BLOB = struct.pack(">II", 0xFADE7171, len(XML) + 8) + XML
DER_BLOB = struct.pack(">II", 0xFADE7172, 10) + b"\x30\x00"


def superblob(entries):
    offset = 12 + len(entries) * 8
    indexes, content = [], []
    for slot, data in entries:
        indexes.append(struct.pack(">II", slot, offset))
        content.append(data)
        offset += len(data)
    return struct.pack(">III", 0xFADE0CC0, offset, len(entries)) + b"".join(indexes + content)


def image(*, defect=None, limit=8192, padding=0, scatter=False, encrypted=False):
    entitlement_slot, entitlement = (
        (7, DER_BLOB) if defect in {"der-zero", "der-missing", "der-at-5"} else (5, XML_BLOB)
    )
    if defect == "misindex":
        entitlement_slot = 2
    elif defect == "xml-at-7":
        entitlement_slot = 7
    elif defect == "der-at-5":
        entitlement_slot = 5
    special = {1: INFO, entitlement_slot: entitlement}
    if defect in {"missing", "der-missing", "misindex"}:
        special = {1: INFO}
    pages = tuple(range((limit + 4095) // 4096))

    def signature(code):
        directory = bytearray(directory_fixture(code[:limit], pages=pages, special=special, scatter=scatter))
        if defect in {"zero", "der-zero"}:
            offset = struct.unpack_from(">I", directory, 16)[0] - entitlement_slot * 32
            directory[offset : offset + 32] = bytes(32)
        return superblob(
            [
                (0, bytes(directory)),
                (entitlement_slot, entitlement),
                (0x10000, struct.pack(">II", 0xFADE0B01, 12) + b"MOCK"),
            ]
        )

    code = bytearray(b"x" * 8192)
    signature_size = len(signature(code)) + padding
    commands = struct.pack("<II16sQQQQiiII", 0x19, 72, b"__TEXT", 0, 8192, 0, 8192, 7, 5, 0, 0)
    commands += struct.pack("<IIII", 0x1D, 16, 8192, signature_size)
    if encrypted:
        commands += struct.pack("<IIIIII", 0x2C, 24, 4096, 4096, 1, 0)
    struct.pack_into(
        "<IIIIIIII", code, 0, 0xFEEDFACF, 0x01000007, 3, 2, 3 if encrypted else 2, len(commands), 0, 0
    )
    code[32 : 32 + len(commands)] = commands
    return bytes(code) + signature(code) + bytes(padding)


@pytest.fixture
def mock_cms(monkeypatch):
    monkeypatch.setattr(
        "mobile_audit.binary_analysis.verify_cms_code_directory",
        lambda *args: {
            "state": "verified",
            "cryptographic_signature_verified": True,
            "certificate_chain_verified": False,
            "explicit_anchor_chain_verified": False,
            "chain_scope": "synthetic-mock-no-trust",
            "chain_anchor_origin": "not-supplied",
            "verification_time_basis": "not-measured",
        },
    )


@pytest.mark.parametrize(
    "defect", ["zero", "missing", "misindex", "xml-at-7", "der-at-5", "der-zero", "der-missing"]
)
def test_unbound_or_wrong_slot_entitlements_never_become_clean(mock_cms, tmp_path, defect):
    raw = image(defect=defect)
    signature = inspect_macho(raw, bundle_blobs={1: INFO})[0]["code_signature"]
    assert signature["integrity"] != "consistent"
    assert signature["signature_integrity"] != "cms-and-code-consistent"
    path = tmp_path / "new-synthetic.ipa"
    with zipfile.ZipFile(path, "w") as archive:
        archive.writestr("Payload/App.app/Info.plist", INFO)
        archive.writestr("Payload/App.app/App", raw)
    report = analyze_binary(path, inspect_target(path)[0])
    assert (
        next(row for row in report["coverage"] if row["rule_id"] == "BINARY-IOS-ENTITLEMENTS")["state"]
        == "partial"
    )


@pytest.mark.parametrize("limit,scatter", [(0, False), (4096, False), (4096, True)])
def test_unsealed_mapped_code_tail_stays_unverifiable(mock_cms, limit, scatter):
    raw = bytearray(image(limit=limit, scatter=scatter))
    raw[5000] ^= 1
    signature = inspect_macho(bytes(raw), bundle_blobs={1: INFO})[0]["code_signature"]
    assert signature["integrity"] == "unverifiable"
    assert signature["signature_integrity"] != "cms-and-code-consistent"
    assert signature["code_directories"][0]["full_code_coverage"] is False


@pytest.mark.parametrize("padding", [0, 4096])
@pytest.mark.parametrize("fat", [False, True])
def test_complete_signed_extent_preserves_padding_and_slice_relative_offsets(mock_cms, padding, fat):
    raw = image(padding=padding)
    if fat:
        header = b"\xca\xfe\xba\xbe" + struct.pack(">IIIIII", 1, 0x01000007, 3, 4096, len(raw), 12)
        raw = header + bytes(4096 - len(header)) + raw
    signature = inspect_macho(raw, bundle_blobs={1: INFO})[0]["code_signature"]
    assert signature["integrity"] == "consistent"
    assert signature["signature_integrity"] == "cms-and-code-consistent"
    assert signature["code_directories"][0]["full_code_coverage"] is True


def test_encrypted_page_postprocessing_cannot_hide_unbound_metadata(mock_cms):
    raw = bytearray(image(defect="zero", encrypted=True))
    raw[5000] ^= 1
    signature = inspect_macho(bytes(raw), bundle_blobs={1: INFO})[0]["code_signature"]
    assert signature["integrity"] == "modified"
    assert signature["code_directories"][0]["entitlements_bound"] is False


def test_encryption_only_retains_not_run_while_unsealed_extent_is_partial(mock_cms, tmp_path):
    from tests.test_parser_depth import large_signed_macho

    for name, raw, expected in [
        ("encrypted-only", large_signed_macho(80), "not-run"),
        ("unsealed-extent", image(limit=4096), "partial"),
    ]:
        path = tmp_path / f"{name}.ipa"
        with zipfile.ZipFile(path, "w") as archive:
            archive.writestr("Payload/App.app/Info.plist", INFO)
            archive.writestr("Payload/App.app/App", raw)
        report = analyze_binary(path, inspect_target(path)[0])
        assert (
            next(row for row in report["coverage"] if row["rule_id"] == "BINARY-IOS-CODE-INTEGRITY")["state"]
            == expected
        )
